def complexPrimitiveKernel (a : ℤ) (q n m : ℕ) : ℂ :=
  (if (((n * m : ℕ) : ℤ) % (q : ℤ) = a % (q : ℤ)) then 1 else 0) -
    (if (n * m).Coprime q then 1 else 0) / (Nat.totient q : ℂ)

def MediumAtom.complexDispersionW (d : MediumAtom) (S : Finset ℕ)
    (w : ℕ → ℝ) : ℝ :=
  ∑ n ∈ S, w n * ‖d.complexProgressionRow n‖ ^ 2

def MediumAtom.complexDispersionU (d : MediumAtom) (S : Finset ℕ)
    (w : ℕ → ℝ) : ℝ :=
  ∑ n ∈ S, w n * ‖d.complexPrincipalRow n‖ ^ 2

def MediumAtom.alphaCarrier (d : MediumAtom) : Finset ℕ :=
  (Finset.Icc (Nat.ceil d.U) (Nat.floor (2 * d.U))).filter
    (fun n => d.intervalLo < (n : ℝ) ∧ (n : ℝ) ≤ d.intervalHi)

def MediumAtom.auxSWError (d : MediumAtom) (k q b : ℕ) : ℂ :=
  (∑ n ∈ d.alphaCarrier,
    if Nat.ModEq q n b ∧ Nat.Coprime n k then d.alpha n else 0) -
  (∑ n ∈ d.alphaCarrier,
    if Nat.Coprime n (k * q) then d.alpha n else 0) / (Nat.totient q : ℂ)
